#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
radio1017.py  上海动感101 FM101.7 时差回放

录：持续拉直播流，按分钟存到 data/rec/<UTC分钟>.mp3，只保留最近 RETAIN_HOURS 小时。
放：本地网页  http://<这台Mac>:8017
    /            手机页面
    /shift.mp3   按「上海同一钟点」回放：你这边 7:00 听到的就是上海 7:00 的节目
    /live.mp3    真正的直播（转发一份给手机）
    /status.json 状态

只用 Python 3.9 自带库，不需要 ffmpeg。
"""
import base64
import json
import os
import re
import select
import socket
import subprocess
import sys
import threading
import time
import urllib.request
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlsplit
from zoneinfo import ZoneInfo

STREAMS = [
    "https://lhttp.qingting.fm/live/274/64k.mp3",
    "https://lhttp-hw.qtfm.cn/live/274/64k.mp3",
]
STATION_NAME = "动感101 FM101.7"
STATION_TZ = ZoneInfo("Asia/Shanghai")
PORT = int(os.environ.get("RADIO_PORT", "8017"))
BIND = os.environ.get("RADIO_BIND", "0.0.0.0")          # 服务器上放在反向代理后面时用 127.0.0.1
KEY = os.environ.get("RADIO_KEY", "").strip("/")        # 设了的话，所有地址都要带 /密钥/ 前缀
# 「我的时间」用哪个时区。不设就用这台机器的系统时区；放到云服务器上必须设，比如 America/New_York
LOCAL_TZ = ZoneInfo(os.environ["RADIO_LOCAL_TZ"]) if os.environ.get("RADIO_LOCAL_TZ") else None
RETAIN_HOURS = 48        # 录音保留多久（64k 一天约 700MB，两天约 1.4GB）
LEAD_SECONDS = 25        # 回放比播放进度多推多少秒，给手机留缓冲
MAX_GAP_MINUTES = 5      # 录音缺口超过这么多分钟就不再硬跳，结束这路流
UA = "radio1017/1.0"

BASE = os.path.dirname(os.path.abspath(__file__))
DATA = os.environ.get("RADIO_DATA") or os.path.join(BASE, "data")
REC = os.path.join(DATA, "rec")
PHOTOS = os.path.join(BASE, "photos")   # 背景风景照（见 photos/CREDITS.md）

rec = None  # Recorder 实例，main() 里创建
LISTENERS = {}  # 客户端 -> 正在放的流数。同一部手机常会开两条连接，所以按客户端去重再数人
_lock = threading.Lock()
_icon = None


def listeners(delta, key):
    with _lock:
        n = LISTENERS.get(key, 0) + delta
        if n <= 0:
            LISTENERS.pop(key, None)
        else:
            LISTENERS[key] = n


def listener_count():
    with _lock:
        return len(LISTENERS)


